import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.Uc5-6EiL.js";const p=JSON.parse('{"title":"0 - JavaScript Setup","description":"","frontmatter":{},"headers":[],"relativePath":"modul/0-javascript-setup.md","filePath":"content/modul/0 - JavaScript Setup.md","lastUpdated":1786621454000}'),r={name:"modul/0-javascript-setup.md"};function s(l,e,o,d,u,c){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="_0-javascript-setup" tabindex="-1">0 - JavaScript Setup <a class="header-anchor" href="#_0-javascript-setup" aria-label="Permalink to &quot;0 - JavaScript Setup&quot;">​</a></h1><p>In diesem Kapitel richtest du alles ein, was du für den JavaScript-Kurs brauchst. Wir arbeiten mit <strong>Visual Studio Code</strong> und einigen Erweiterungen, die uns das Programmieren erleichtern.</p><h2 id="visual-studio-code-installieren" tabindex="-1">Visual Studio Code installieren <a class="header-anchor" href="#visual-studio-code-installieren" aria-label="Permalink to &quot;Visual Studio Code installieren&quot;">​</a></h2><p>Visual Studio Code, kurz <strong>VS Code</strong>, ist der Editor, in dem wir unseren Code schreiben.</p><ol><li>Lade <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code</a> herunter.</li><li>Installiere das Programm auf deinem Computer.</li><li>Starte VS Code.</li></ol><h2 id="extensions-installieren" tabindex="-1">Extensions installieren <a class="header-anchor" href="#extensions-installieren" aria-label="Permalink to &quot;Extensions installieren&quot;">​</a></h2><p>Extensions sind Erweiterungen für VS Code. Sie fügen dem Editor zusätzliche Funktionen hinzu.</p><p>So installierst du eine Extension:</p><ol><li>Klicke links in VS Code auf das <strong>Extensions-Symbol</strong> mit den vier Vierecken.</li><li>Gib den Namen der Extension in das Suchfeld ein.</li><li>Achte darauf, dass du die richtige Extension ausgewählt hast.</li><li>Klicke auf <strong>Install</strong>.</li></ol><p>Installiere diese Extensions:</p><ul><li><a href="https://marketplace.visualstudio.com/items?itemName=ritwickdey.LiveServer" target="_blank" rel="noreferrer">Live Server</a>: Zeigt deine Webseite im Browser an und aktualisiert sie nach dem Speichern.</li><li><a href="https://marketplace.visualstudio.com/items?itemName=esbenp.prettier-vscode" target="_blank" rel="noreferrer">Prettier</a>: Formatiert deinen Code automatisch.</li><li><a href="https://marketplace.visualstudio.com/items?itemName=dbaeumer.vscode-eslint" target="_blank" rel="noreferrer">ESLint</a>: Hilft dir, Fehler im JavaScript-Code zu erkennen.</li><li><a href="https://marketplace.visualstudio.com/items?itemName=MS-vsliveshare.vsliveshare" target="_blank" rel="noreferrer">Live Share</a>: Ermöglicht gemeinsames Arbeiten an einem Projekt.</li></ul><h2 id="prettier-einrichten" tabindex="-1">Prettier einrichten <a class="header-anchor" href="#prettier-einrichten" aria-label="Permalink to &quot;Prettier einrichten&quot;">​</a></h2><p>Damit Prettier deinen Code beim Speichern automatisch formatiert, passen wir zwei Einstellungen an.</p><h3 id="format-on-save-aktivieren" tabindex="-1">Format On Save aktivieren <a class="header-anchor" href="#format-on-save-aktivieren" aria-label="Permalink to &quot;Format On Save aktivieren&quot;">​</a></h3><ol><li>Öffne die Einstellungen mit <code>Cmd + ,</code> auf dem Mac oder <code>Ctrl + ,</code> unter Windows.</li><li>Suche nach <code>Format On Save</code>.</li><li>Aktiviere die Einstellung <strong>Editor: Format On Save</strong>.</li></ol><h3 id="prettier-als-standard-formatter-auswahlen" tabindex="-1">Prettier als Standard-Formatter auswählen <a class="header-anchor" href="#prettier-als-standard-formatter-auswahlen" aria-label="Permalink to &quot;Prettier als Standard-Formatter auswählen&quot;">​</a></h3><ol><li>Suche in den Einstellungen nach <code>Default Formatter</code>.</li><li>Wähle <strong>Prettier - Code formatter</strong> aus.</li></ol><p>Wenn du eine Datei speicherst, wird dein Code nun automatisch sauber formatiert.</p><h2 id="einen-projektordner-offnen" tabindex="-1">Einen Projektordner öffnen <a class="header-anchor" href="#einen-projektordner-offnen" aria-label="Permalink to &quot;Einen Projektordner öffnen&quot;">​</a></h2><p>Ein JavaScript-Projekt besteht meistens aus mehreren Dateien. Deshalb öffnen wir in VS Code immer den <strong>ganzen Projektordner</strong> und nicht nur eine einzelne Datei.</p><ol><li>Entpacke den heruntergeladenen Projektordner.</li><li>Öffne VS Code.</li><li>Klicke auf <strong>File → Open Folder</strong>.</li><li>Wähle den entpackten Ordner aus.</li><li>Klicke auf <strong>Open</strong>.</li></ol><p>Links in VS Code siehst du danach die Dateien des Projekts, zum Beispiel:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>projekt/</span></span>
<span class="line"><span>├── index.html</span></span>
<span class="line"><span>├── style.css</span></span>
<span class="line"><span>└── script.js</span></span></code></pre></div><h2 id="eine-webseite-mit-live-server-starten" tabindex="-1">Eine Webseite mit Live Server starten <a class="header-anchor" href="#eine-webseite-mit-live-server-starten" aria-label="Permalink to &quot;Eine Webseite mit Live Server starten&quot;">​</a></h2><ol><li>Öffne in VS Code die Datei <code>index.html</code>.</li><li>Klicke unten rechts auf <strong>Go Live</strong>.</li></ol><p>Alternativ kannst du mit der rechten Maustaste auf <code>index.html</code> klicken und <strong>Open with Live Server</strong> auswählen.</p><p>Die Webseite öffnet sich nun im Browser. Wenn du eine Datei veränderst und speicherst, aktualisiert Live Server die Webseite.</p><h2 id="setup-abgeschlossen" tabindex="-1">Setup abgeschlossen <a class="header-anchor" href="#setup-abgeschlossen" aria-label="Permalink to &quot;Setup abgeschlossen&quot;">​</a></h2><p>Du bist bereit, wenn:</p><ul><li>VS Code installiert ist,</li><li>Live Server, Prettier, ESLint und Live Share installiert sind,</li><li>Format On Save aktiviert ist und</li><li>Prettier als Standard-Formatter ausgewählt ist.</li></ul><p>Im nächsten Kapitel lädst du das erste vorbereitete Projekt herunter und machst eine Webseite mit JavaScript interaktiv.</p>`,31)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
